	private static void assertAbsentOwnerDoesNotReadProperties(String query) {
		CountingTripleSource source = sourceWithUnrelatedProperties(1_024);

		List<BindingSet> result = rows(query, source);

		assertThat(result).hasSize(1);
		assertThat(result.getFirst().hasBinding("name")).isFalse();
		assertThat(source.propertyLookups).as("property lookups for an absent owner").isZero();
		assertThat(source.propertyStatementsRead).isZero();
	}

	@Test
	void aNullableBoundOwnerDoesNotReadUnrelatedOwners() {
		for (int unrelatedOwners : new int[] { 0, 2_048 }) {
			CountingTripleSource source = sourceWithUnrelatedProperties(unrelatedOwners);
			source.add(SEED, KNOWS, ALICE);
			source.add(ALICE, NAME, VF.createLiteral("Alice"));

			assertThat(column(rows(OPTIONAL_PROPERTY, source), "name"))
					.containsExactly(VF.createLiteral("Alice"));
			assertThat(source.propertyLookupSubjects).as("property lookup owners with %s unrelated owners",
					unrelatedOwners).containsExactly(ALICE);
			assertThat(source.propertyStatementsRead).as("property terms read with %s unrelated owners",
					unrelatedOwners).isEqualTo(1);
			assertThat(source.propertyCursorsClosed).isEqualTo(source.propertyLookups);
		}
	}

	@Test
	void theSecondDistinctLiteralEndsTheScanAndClosesItsCursor() {
		CountingTripleSource source = personSource();
		source.add(ALICE, NAME, VF.createLiteral("Alice"), FIRST_GRAPH);
		source.add(ALICE, NAME, VF.createLiteral("Alice"), SECOND_GRAPH);
		source.add(ALICE, NAME, VF.createLiteral("Alicia"), FIRST_GRAPH);
		for (int i = 0; i < 256; i++) {
			source.add(ALICE, NAME, VF.createLiteral("later-" + i));
		}

		assertThatThrownBy(() -> rows("MATCH (n:Person) RETURN n.name AS name", source))
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("multiple");
		assertThat(source.propertyStatementsRead).as("read only through the second distinct RDF term")
				.isEqualTo(3);
		assertThat(source.propertyCursorsClosed).isEqualTo(source.propertyLookups);
	}

